// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { complex128ndarray, typedndarray } from '@stdlib/types/ndarray';
import { Complex128 } from '@stdlib/types/complex';

/**
* Replaces elements in a one-dimensional double-precision complex floating-point ndarray equal to `NaN` with a specified scalar constant.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the scalar constant.
*     -   a zero-dimensional ndarray containing the starting index (inclusive).
*     -   a zero-dimensional ndarray containing the ending index (exclusive).
*
* -   A complex number is considered `NaN` if either the real or imaginary component is `NaN`.
*
* @param arrays - array-like object containing ndarrays
* @returns input ndarray
*
* @example
* var Complex128Vector = require( '@stdlib/ndarray/vector/complex128' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
*
* var x = new Complex128Vector( [ NaN, NaN, -2.0, 3.0, 4.0, 5.0, 4.0, -6.0 ] );
*
* var alpha = scalar2ndarray( new Complex128( 0.0, 0.0 ), {
*     'dtype': 'complex128'
* });
*
* var start = scalar2ndarray( 0, {
*     'dtype': 'generic'
* });
*
* var end = scalar2ndarray( 2, {
*     'dtype': 'generic'
* });
*
* var out = zfillNaN( [ x, alpha, start, end ] );
* // returns <ndarray>[ <Complex128>[ 0.0, 0.0 ], <Complex128>[ -2.0, 3.0 ], <Complex128>[ 4.0, 5.0 ], <Complex128>[ 4.0, -6.0 ] ]
*/
declare function zfillNaN( arrays: [ complex128ndarray, typedndarray<Complex128>, typedndarray<number>, typedndarray<number> ] ): complex128ndarray;


// EXPORTS //

export = zfillNaN;
